#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must be a UPROPERTY: without a tracked reference the garbage
	// collector destroys the NewObject'd tracker after BeginPlay, leaving
	// this pointer dangling (crash in AddPoints on the first goal).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker* ScoreTracker was a raw UObject pointer without UPROPERTY, so the garbage collector did not see the reference and destroyed the NewObject'd tracker shortly after BeginPlay (log: 'LogGarbage: Collecting garbage: 412 objects purged' at 21:05:13). OnGoalScored then called AddPoints() on the dangling pointer (log: 'Unhandled Exception: EXCEPTION_ACCESS_VIOLATION ... UArenaScoreTracker::AddPoints() [ArenaScoreTracker.cpp:18] <- AArenaGameMode::OnGoalScored() [ArenaGameMode.cpp:38]'), a few tens of seconds into play, matching 'crashes after a minute'. Fix: ScoreTracker is now UPROPERTY() TObjectPtr<> in ArenaGameMode.h so it is root-referenced and survives GC.",
  "no_colors_cause": "The arena palette asset is only loaded at runtime by hardcoded path LoadObject(TEXT(\"/Game/Data/Palettes/DA_Primary.DA_Primary\")); with bCookAll=False and no cook rule for /Game/Data/Palettes, the cook (only /Game/Maps/Arena and /Game/Data/Effects were included) never packaged that asset, so the packaged build logged 'Couldn't find file for package /Game/Data/Palettes/DA_Primary' and the game fell back to gray ('Palette is null, using fallback gray'). Fix: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini so the data assets are cooked into the pak."
}
